      esac
      return 0
      ;;
    completion)
      if [[ "$cword" -eq 2 ]]; then
        if [[ "$cur" == -* ]]; then
          COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
        else
          COMPREPLY=( $(compgen -W "install uninstall status" \
            -- "$cur") )
        fi
        return 0
      fi
      case "${COMP_WORDS[2]}" in
        install)
